PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?cohort
       (COUNT(DISTINCT ?g) AS ?patients)
       (SUM(IF(?lab_tests > 0, 1, 0)) AS ?patients_with_lab_test)
       (ROUND(1000.0 * SUM(IF(?lab_tests > 0, 1, 0)) / COUNT(DISTINCT ?g)) / 10 AS ?pct_with_lab_test)
       (ROUND(10 * AVG(?lab_tests)) / 10 AS ?avg_lab_tests_per_patient)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?lab_test) AS ?lab_tests)
    WHERE {
      GRAPH ?g { ?sex_record a sphn:AdministrativeSex . }
      OPTIONAL { GRAPH ?g { ?lab_test a sphn:LabTestEvent . } }
    }
    GROUP BY ?g
  }
  BIND (IF(EXISTS {
             GRAPH ?g {
               ?dx a sphn:BilledDiagnosis ;
                   sphn:hasCode ?dx_code .
               ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
             }
           }, "with cholera", "other patients") AS ?cohort)
}
GROUP BY ?cohort
ORDER BY ?cohort

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_allergy)
       (COUNT(DISTINCT ?adverse_event_patient) AS ?patients_with_adverse_event)
       (ROUND(1000.0 * COUNT(DISTINCT ?adverse_event_patient) / COUNT(DISTINCT ?g)) / 10 AS ?pct_with_adverse_event)
WHERE {
  GRAPH ?g { ?allergy a sphn:Allergy . }
  OPTIONAL {
    GRAPH ?g { ?event a sphn:AdverseEvent . }
    BIND (?g AS ?adverse_event_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?decade ?sex (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?age a sphn:Age ;
         sphn:hasQuantity/sphn:hasValue ?age_value .
    ?sex_record a sphn:AdministrativeSex ;
                sphn:hasCode ?sex_code .
    ?sex_code a ?sex_concept .
  }
  VALUES (?sex_concept ?sex) {
    (snomed:248153007         "male")
    (snomed:248152002         "female")
    (snomed:32570681000036106 "indeterminate")
  }
  { GRAPH ?g { ?drug_event a sphn:DrugPrescription . } }
  UNION
  { GRAPH ?g { ?drug_event a sphn:DrugAdministrationEvent . } }
  BIND (10 * FLOOR(?age_value / 10) AS ?decade)
}
GROUP BY ?decade ?sex
ORDER BY ?decade ?sex
